11	export const k8sUpdateCommand = defineCommand({
12	  description: 'Update a Kubernetes cluster metadata or features',
13	  since: 'unreleased',
14	  options: {
15	    name: defineOption({
16	      name: 'name',
17	      schema: z.string().max(128).optional(),
18	      description: 'Rename the cluster',
19	      placeholder: 'name',
20	    }),
21	    description: defineOption({
22	      name: 'description',
23	      schema: z.string().max(4096).optional(),
24	      description: 'Free-form cluster description',
25	      placeholder: 'description',
26	    }),
27	    tag: defineOption({
28	      name: 'tag',
29	      schema: z.string().transform(tags).optional(),
30	      description: 'Replace tags (comma-separated, e.g.: env:prod,team:platform)',
31	      placeholder: 'tag[,tag...]',
32	    }),
33	    autoscaling: defineOption({
34	      name: 'autoscaling',
35	      schema: z.boolean().default(false),
36	      description: 'Enable the cluster autoscaler',
37	    }),
38	    disableAutoscaling: defineOption({
39	      name: 'disable-autoscaling',
40	      schema: z.boolean().default(false),
41	      description: 'Disable the cluster autoscaler',
42	    }),
43	    org: orgaIdOrNameOption,
44	  },
45	  args: [k8sIdOrNameArg],
46	  async handler(options, clusterIdOrName) {
47	    const { org: orgIdOrName } = options;
48	
49	    if (options.autoscaling && options.disableAutoscaling) {
50	      throw new Error('--autoscaling and --disable-autoscaling are mutually exclusive');
51	    }
52	
53	    const updates = {};
54	    if (options.name != null) updates.name = options.name;
55	    if (options.description != null) updates.description = options.description;
56	    if (options.tag != null) updates.tags = options.tag;
57	
58	    const features = {};
59	    if (options.autoscaling) features.autoscalingEnabled = true;
60	    if (options.disableAutoscaling) features.autoscalingEnabled = false;
61	    if (Object.keys(features).length > 0) updates.features = features;
62	
63	    if (Object.keys(updates).length === 0) {
64	      throw new Error(
65	        'No update specified. Provide at least one of --name, --description, --tag, --autoscaling, --disable-autoscaling',
66	      );
67	    }
68	
69	    const cluster = await k8sUpdate(orgIdOrName, clusterIdOrName, updates);
70	    Logger.printSuccess(`Cluster ${styleText('green', cluster.name)} updated`);
71	  },
72	});
